//! Explicit storage format versioning and compatibility with a real database
//! written by AeroDB 0.5.1 (tests/fixtures/aerodb-0.5.1, generated by the
//! 0.5.1 code at commit 675fdcd; see the provenance log in the task report).
//! The committed fixture files are never opened in place: every test works
//! on a copy inside a temporary directory.
mod common;

use aerodb::db::Database;
use aerodb::engine::Engine;
use aerodb::storage::pager::STORAGE_FORMAT_VERSION;
use common::{exec, rows, sorted, table};
use std::fs;
use std::path::{Path, PathBuf};
use tempfile::TempDir;

const FIXTURE_FILES: [&str; 3] = ["fixture.db", "fixture.db.wal", "fixture.db.clog"];
/// Committed sizes (bytes) of the fixture files, as logged at generation.
const FIXTURE_LENS: [u64; 3] = [28672, 35, 11];

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/aerodb-0.5.1")
}

fn fixture_bytes() -> Vec<Vec<u8>> {
    FIXTURE_FILES
        .iter()
        .map(|f| fs::read(fixture_dir().join(f)).expect("fixture file"))
        .collect()
}

/// Copy the 0.5.1 fixture (main file + sidecars) into a fresh temp dir and
/// return the path of the copied main file.
fn copy_fixture() -> (TempDir, PathBuf) {
    let dir = tempfile::tempdir().expect("tempdir");
    for f in FIXTURE_FILES {
        fs::copy(fixture_dir().join(f), dir.path().join(f)).expect("copy fixture");
    }
    let path = dir.path().join("fixture.db");
    (dir, path)
}

fn open(path: &Path) -> Engine {
    Engine::new(path.to_str().unwrap())
}

fn q(e: &mut Engine, sql: &str) -> Vec<Vec<String>> {
    rows(e, sql).unwrap_or_else(|m| panic!("`{sql}` failed: {m}"))
}

fn q_set(e: &mut Engine, sql: &str) -> Vec<Vec<String>> {
    sorted(q(e, sql))
}

fn meta_version(path: &Path) -> u32 {
    let bytes = fs::read(path).unwrap();
    u32::from_le_bytes(bytes[32..36].try_into().unwrap())
}

fn assert_fixture_content(e: &mut Engine) {
    assert_eq!(
        q(e, "SELECT id, name, score, born FROM users ORDER BY id"),
        table(&[
            &["1", "ann", "10.5", "1990-01-02"],
            &["2", "bob", "NULL", "1985-12-31"],
            &["3", "cy", "7.25", "NULL"],
        ])
    );
    // The 0.5.1 generator's `DELETE FROM orders WHERE id = 12` ran inside
    // transaction 9, which 0.5.1 left open after the failed UPDATE (WAL: begin
    // 9 without commit; clog: 9 = active), so recovery aborts it and order 12
    // is still there -- exactly what 0.5.1 itself reads back.
    assert_eq!(
        q(e, "SELECT id, user_id FROM orders ORDER BY id"),
        table(&[&["10", "1"], &["11", "1"], &["12", "2"]])
    );
    assert_eq!(
        q_set(e, "SELECT a, b FROM nopk"),
        table(&[&["1", "x"], &["2", "y"]])
    );
    assert_eq!(q(e, "SELECT COUNT(*) FROM padded"), table(&[&["0"]]));
}

#[test]
fn fixture_is_a_0_5_1_file() {
    let bytes = fixture_bytes();
    for (b, len) in bytes.iter().zip(FIXTURE_LENS) {
        assert_eq!(b.len() as u64, len);
    }
    // 0.5.1 wrote the meta page without a format version (zeroed bytes 32..36).
    assert_eq!(&bytes[0][0..8], b"AERODBM1");
    assert_eq!(&bytes[0][32..36], &[0, 0, 0, 0]);
    assert_eq!(STORAGE_FORMAT_VERSION, 2);
}

#[test]
fn reads_0_5_1_fixture() {
    let before = fixture_bytes();
    let (_dir, path) = copy_fixture();
    let mut e = open(&path);
    assert_fixture_content(&mut e);
    // Header types come from the 0.5.1 catalog rows.
    let types: Vec<String> = e
        .query("SELECT id, name, score, born FROM users")
        .unwrap()
        .columns
        .iter()
        .map(|c| c.ty.name())
        .collect();
    assert_eq!(types, vec!["INTEGER", "TEXT", "DOUBLE", "DATE"]);
    drop(e);
    // The committed fixture is untouched.
    assert_eq!(fixture_bytes(), before);
}

#[test]
fn writes_to_0_5_1_fixture() {
    let before = fixture_bytes();
    let (dir, path) = copy_fixture();
    let mut e = open(&path);

    // Cases 0.5.1 itself rejected now work.
    exec(&mut e, "INSERT INTO padded (code) VALUES ('ab')");
    assert_eq!(
        q(&mut e, "SELECT code, qty FROM padded"),
        table(&[&["ab  ", "5"]])
    );
    exec(&mut e, "UPDATE users SET name = 'bobby' WHERE id = 2");
    assert_eq!(
        q(&mut e, "SELECT name FROM users WHERE id = 2"),
        table(&[&["bobby"]])
    );

    // Tables without a primary key: new row ids never collide with the
    // legacy physical keys (0.5.1 keyed nopk by its first column).
    exec(&mut e, "INSERT INTO nopk VALUES (1, 'dup'), (3, 'z')");
    exec(&mut e, "INSERT INTO nopk VALUES (2, 'y2')");
    assert_eq!(
        q_set(&mut e, "SELECT a, b FROM nopk"),
        table(&[
            &["1", "dup"],
            &["1", "x"],
            &["2", "y"],
            &["2", "y2"],
            &["3", "z"]
        ])
    );
    exec(&mut e, "UPDATE nopk SET b = 'X' WHERE b = 'x'");
    exec(&mut e, "DELETE FROM nopk WHERE b = 'y'");
    assert_eq!(
        q_set(&mut e, "SELECT a, b FROM nopk"),
        table(&[&["1", "X"], &["1", "dup"], &["2", "y2"], &["3", "z"]])
    );

    // INSERT/UPDATE/DELETE on keyed tables; the FOREIGN KEY is still enforced.
    exec(
        &mut e,
        "INSERT INTO users VALUES (4, 'dee', 1.5, '2000-02-29')",
    );
    assert_eq!(
        err_state(&mut e, "INSERT INTO users VALUES (4, 'dup', NULL, NULL)"),
        "23505"
    );
    exec(&mut e, "INSERT INTO orders VALUES (13, 4)");
    assert_eq!(
        err_state(&mut e, "INSERT INTO orders VALUES (14, 99)"),
        "23503"
    );
    assert_eq!(err_state(&mut e, "DELETE FROM users WHERE id = 1"), "23503");
    assert_eq!(
        err_state(&mut e, "UPDATE users SET id = 40 WHERE id = 4"),
        "23503"
    );
    exec(&mut e, "DELETE FROM users WHERE id = 3");
    exec(&mut e, "UPDATE users SET score = score * 2 WHERE id = 1");

    // New 0.6.0 DDL on the old file.
    exec(
        &mut e,
        "ALTER TABLE users ADD COLUMN tier INTEGER DEFAULT 1",
    );
    exec(
        &mut e,
        "CREATE VIEW big_spenders AS SELECT u.name, COUNT(*) AS n FROM users u JOIN orders o ON o.user_id = u.id GROUP BY u.name",
    );

    let expect_after = |e: &mut Engine| {
        assert_eq!(
            q(
                e,
                "SELECT id, name, score, born, tier FROM users ORDER BY id"
            ),
            table(&[
                &["1", "ann", "21", "1990-01-02", "1"],
                &["2", "bobby", "NULL", "1985-12-31", "1"],
                &["4", "dee", "1.5", "2000-02-29", "1"],
            ])
        );
        assert_eq!(
            q(e, "SELECT id, user_id FROM orders ORDER BY id"),
            table(&[&["10", "1"], &["11", "1"], &["12", "2"], &["13", "4"]])
        );
        assert_eq!(
            q_set(e, "SELECT name, n FROM big_spenders"),
            table(&[&["ann", "2"], &["bobby", "1"], &["dee", "1"]])
        );
        assert_eq!(
            q(e, "SELECT code, qty FROM padded"),
            table(&[&["ab  ", "5"]])
        );
        assert_eq!(
            q_set(e, "SELECT a, b FROM nopk"),
            table(&[&["1", "X"], &["1", "dup"], &["2", "y2"], &["3", "z"]])
        );
    };
    expect_after(&mut e);
    drop(e);

    // Every commit wrote the current format version.
    assert_eq!(meta_version(&path), STORAGE_FORMAT_VERSION);

    // Reopen and re-read.
    let mut e = open(&path);
    expect_after(&mut e);
    exec(&mut e, "INSERT INTO nopk VALUES (4, 'w')");
    assert_eq!(
        err_state(&mut e, "INSERT INTO orders VALUES (15, 3)"),
        "23503"
    );
    drop(e);
    let mut e = open(&path);
    assert_eq!(q(&mut e, "SELECT COUNT(*) FROM nopk"), table(&[&["5"]]));
    drop(e);
    drop(dir);
    assert_eq!(fixture_bytes(), before);
}

fn err_state(e: &mut Engine, sql: &str) -> &'static str {
    common::err(e, sql).sqlstate()
}

// ---------------------------------------------------------------------------
// G4: a 0.5.1 table whose INTEGER PRIMARY KEY is not the first column
// (tests/fixtures/aerodb-0.5.1-nonfirst, generated by the 0.5.1 code at
// 675fdcd; provenance and sha256 in the task 7b report). 0.5.1 keyed the rows
// physically by the first column (a = 1, 2), not by the primary key n.
// ---------------------------------------------------------------------------

/// Committed sizes (bytes) of the non-first-PK fixture files.
const NONFIRST_LENS: [u64; 3] = [16384, 8, 9];

fn nonfirst_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/aerodb-0.5.1-nonfirst")
}

fn nonfirst_bytes() -> Vec<Vec<u8>> {
    FIXTURE_FILES
        .iter()
        .map(|f| fs::read(nonfirst_dir().join(f)).expect("fixture file"))
        .collect()
}

fn copy_nonfirst() -> (TempDir, PathBuf) {
    let dir = tempfile::tempdir().expect("tempdir");
    for f in FIXTURE_FILES {
        fs::copy(nonfirst_dir().join(f), dir.path().join(f)).expect("copy fixture");
    }
    let path = dir.path().join("fixture.db");
    (dir, path)
}

/// Every lookup path agrees on the content `rows` (a, n), sorted by n.
fn assert_nonfirst(e: &mut Engine, rows: &[(&str, &str)]) {
    let all: Vec<Vec<String>> = rows
        .iter()
        .map(|(a, n)| vec![a.to_string(), n.to_string()])
        .collect();
    assert_eq!(q(e, "SELECT a, n FROM old_nonfirst ORDER BY n"), all);
    assert_eq!(
        q(e, "SELECT COUNT(*) FROM old_nonfirst"),
        table(&[&[&rows.len().to_string()]])
    );
    for (a, n) in rows {
        assert_eq!(
            q(e, &format!("SELECT a, n FROM old_nonfirst WHERE n = {n}")),
            table(&[&[a, n]]),
            "lookup n = {n}"
        );
        // Every existing key is rejected as a duplicate.
        assert_eq!(
            err_state(e, &format!("INSERT INTO old_nonfirst VALUES (77, {n})")),
            "23505",
            "dup n = {n}"
        );
    }
}

#[test]
fn nonfirst_fixture_is_a_0_5_1_file() {
    let bytes = nonfirst_bytes();
    for (b, len) in bytes.iter().zip(NONFIRST_LENS) {
        assert_eq!(b.len() as u64, len);
    }
    assert_eq!(&bytes[0][0..8], b"AERODBM1");
    assert_eq!(&bytes[0][32..36], &[0, 0, 0, 0]);
}

#[test]
fn legacy_nonfirst_integer_primary_key_keeps_identity() {
    let before = nonfirst_bytes();
    let (dir, path) = copy_nonfirst();
    let mut e = open(&path);
    assert_nonfirst(&mut e, &[("1", "100"), ("2", "200")]);

    exec(&mut e, "UPDATE old_nonfirst SET a = 9 WHERE n = 200");
    assert_nonfirst(&mut e, &[("1", "100"), ("9", "200")]);
    exec(&mut e, "DELETE FROM old_nonfirst WHERE n = 100");
    assert_nonfirst(&mut e, &[("9", "200")]);
    // n = 1 is the alias key of the new row, but legacy physical key 1 held
    // the deleted row (1, 100): the two must stay distinct rows.
    exec(&mut e, "INSERT INTO old_nonfirst VALUES (5, 500), (6, 1)");
    assert_nonfirst(&mut e, &[("6", "1"), ("9", "200"), ("5", "500")]);
    // n = 2 collides with the live legacy row (9, 200) stored under key 2.
    exec(&mut e, "INSERT INTO old_nonfirst VALUES (7, 2)");
    assert_nonfirst(
        &mut e,
        &[("6", "1"), ("7", "2"), ("9", "200"), ("5", "500")],
    );
    // Changing the primary key of a legacy row.
    exec(&mut e, "UPDATE old_nonfirst SET n = 300 WHERE n = 200");
    assert_eq!(
        err_state(&mut e, "UPDATE old_nonfirst SET n = 1 WHERE n = 300"),
        "23505"
    );
    assert_nonfirst(
        &mut e,
        &[("6", "1"), ("7", "2"), ("9", "300"), ("5", "500")],
    );

    // Index lookups on the primary key.
    exec(&mut e, "CREATE INDEX idx_n ON old_nonfirst (n)");
    assert_nonfirst(
        &mut e,
        &[("6", "1"), ("7", "2"), ("9", "300"), ("5", "500")],
    );
    exec(&mut e, "UPDATE old_nonfirst SET a = 70 WHERE n = 2");
    exec(&mut e, "DELETE FROM old_nonfirst WHERE n = 1");
    let expected = [("70", "2"), ("9", "300"), ("5", "500")];
    assert_nonfirst(&mut e, &expected);
    drop(e);

    let mut e = open(&path);
    assert_nonfirst(&mut e, &expected);
    exec(&mut e, "CREATE INDEX idx_n ON old_nonfirst (n)");
    assert_nonfirst(&mut e, &expected);
    exec(&mut e, "INSERT INTO old_nonfirst VALUES (11, 1)");
    exec(&mut e, "UPDATE old_nonfirst SET a = 12 WHERE n = 1");
    let expected = [("12", "1"), ("70", "2"), ("9", "300"), ("5", "500")];
    assert_nonfirst(&mut e, &expected);
    drop(e);

    // The same through the concurrent Database API after another reopen.
    let db = Database::open(path.to_str().unwrap()).unwrap();
    let tx = db.begin().unwrap();
    let r = db
        .query(&tx, "SELECT a, n FROM old_nonfirst ORDER BY n")
        .unwrap();
    let got: Vec<Vec<String>> = r
        .rows
        .iter()
        .map(|row| row.iter().map(|v| v.to_string()).collect())
        .collect();
    assert_eq!(
        got,
        table(&[&["12", "1"], &["70", "2"], &["9", "300"], &["5", "500"]])
    );
    assert_eq!(db.query_all(&tx, "old_nonfirst").unwrap().len(), 4);
    db.commit(tx).unwrap();
    drop(db);
    drop(dir);
    assert_eq!(nonfirst_bytes(), before);
}

#[test]
fn new_database_records_format_version() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("fresh.db");
    let mut e = open(&path);
    exec(&mut e, "CREATE TABLE t (id INTEGER PRIMARY KEY)");
    exec(&mut e, "INSERT INTO t VALUES (1)");
    drop(e);
    assert_eq!(meta_version(&path), 2);
    let mut e = open(&path);
    assert_eq!(q(&mut e, "SELECT id FROM t"), table(&[&["1"]]));
}

#[test]
fn unknown_format_version_is_rejected_without_modification() {
    let (dir, path) = copy_fixture();
    // Bring the copy up to date first (opening replays the 0.5.1 WAL), then
    // patch the version to one this build does not know.
    {
        let mut e = open(&path);
        exec(&mut e, "INSERT INTO nopk VALUES (9, 'v')");
    }
    let mut bytes = fs::read(&path).unwrap();
    bytes[32..36].copy_from_slice(&99u32.to_le_bytes());
    fs::write(&path, &bytes).unwrap();
    let sidecars = |p: &Path| -> Vec<Option<Vec<u8>>> {
        ["wal", "clog"]
            .iter()
            .map(|ext| fs::read(format!("{}.{}", p.display(), ext)).ok())
            .collect()
    };
    let sidecars_before = sidecars(&path);

    let err = match Database::open(path.to_str().unwrap()) {
        Ok(_) => panic!("a version-99 file must not open"),
        Err(e) => e,
    };
    assert_eq!(
        err.to_string(),
        "unsupported AeroDB storage format version 99 (this build supports up to 2)"
    );
    let err = match Engine::open(path.to_str().unwrap()) {
        Ok(_) => panic!("a version-99 file must not open"),
        Err(e) => e,
    };
    assert!(
        err.to_string()
            .contains("unsupported AeroDB storage format version 99"),
        "{err}"
    );
    assert_eq!(
        fs::read(&path).unwrap(),
        bytes,
        "a rejected file must not be modified"
    );
    assert_eq!(
        sidecars(&path),
        sidecars_before,
        "sidecars must not be modified"
    );

    // Version 0 (0.5.x) and the current version open.
    for ok in [0u32, STORAGE_FORMAT_VERSION] {
        let mut patched = bytes.clone();
        patched[32..36].copy_from_slice(&ok.to_le_bytes());
        fs::write(&path, &patched).unwrap();
        let db =
            Database::open(path.to_str().unwrap()).unwrap_or_else(|e| panic!("version {ok}: {e}"));
        drop(db);
    }
    drop(dir);
}
